440	/// Ensures a lone HTML element/frame renders as its own block.
441	///
442	/// Configures the `display` property of the HTML node (if it is an element or
443	/// frame).
444	fn make_block_level(node: &mut HtmlNode) -> Result<(), Unblockable> {
445	    let default = match node {
446	        // A math element's default display property depends on its `display`
447	        // attribute.
448	        HtmlNode::Element(element)
449	            if element.tag == tag::mathml::math
450	                && element
451	                    .attrs
452	                    .get(attr::mathml::display)
453	                    .is_some_and(|v| v == "block") =>
454	        {
455	            Some(property::Display::BlockMath)
456	        }
457	        HtmlNode::Element(element) => property::Display::default_for(element.tag),
458	        HtmlNode::Frame(_) => Some(property::Display::Inline),
459	        _ => return Err(Unblockable),
460	    };
461	
462	    let mode = match default {
463	        // These can be left unchanged / have `display` unset because they are
464	        // either invisible or already render in a block-level way.
465	        Some(
466	            property::Display::None
467	            | property::Display::Block
468	            | property::Display::Table
469	            | property::Display::ListItem
470	            | property::Display::Contents
471	            | property::Display::BlockMath,
472	        ) => None,
473	
474	        // These must be promoted to `block`.
475	        None | Some(property::Display::Inline | property::Display::InlineBlock) => {
476	            Some(property::Display::Block)
477	        }
478	        Some(property::Display::InlineMath) => Some(property::Display::BlockMath),
479	
480	        // These can't be promoted. They are instead wrapped in a `<div>`.
481	        _ => return Err(Unblockable),
482	    };
483	
484	    set_display(node, mode);
485	    Ok(())
486	}
